// ====================================
// TODO EN UNO: Extraer datos + Construir body
// ====================================

// Intentar obtener del webhook original o del nodo procesador
let telefono, instancia;

// Si viene del webhook directo
if ($json.body?.data) {
  const data = $json.body.data;
  telefono = data.key.remoteJid.replace('@s.whatsapp.net', '');
  instancia = $json.body.instance || 'Hemisferia';
}
// Si viene de un nodo procesador anterior
else if ($json.telefono) {
  telefono = $json.telefono;
  instancia = $json.instancia || 'Hemisferia';
}
// Intentar desde el input del primer nodo
else {
  const webhook = $('Webhook').item.json;
  const data = webhook.body?.data || webhook.data;
  telefono = data.key.remoteJid.replace('@s.whatsapp.net', '');
  instancia = webhook.body?.instance || webhook.instance || 'Hemisferia';
}

// Obtener respuesta del Agente IA (este nodo)
const respuesta = $json.output;

// Validar
if (!telefono) {
  throw new Error('No se pudo extraer el teléfono');
}

if (!respuesta) {
  throw new Error('No hay respuesta del Agente IA');
}

return {
  json: {
    number: telefono,
    textMessage: {
      text: respuesta
    },
    instancia: instancia
  }
};

